-- 2026-08 quality repair: restore buyer-facing product copy.  The catalogue
-- keeps all 227 candidates; descriptions no longer contain benchmark workflow
-- language such as “写入台账/下一步/当前候选”.
UPDATE products SET description = '薄掌垫、透气网布，适合短途练习；尺码按掌围选择。' WHERE product_id = 'prod_tri_glove_basic_052';
UPDATE products SET description = '弹力带配三个固定点，可快速别号码布；首次使用先调整腰围。' WHERE product_id = 'prod_tri_race_belt_052';
UPDATE products SET description = '透明镜片适合室内泳池，鼻桥可调；防雾层需用清水轻洗。' WHERE product_id = 'prod_tri_goggle_052';

UPDATE products
SET description = CASE (rowid % 40)
  WHEN 0 THEN '哑光表面，擦拭后阴干。'
  WHEN 1 THEN '轻量结构，初次使用先调松紧。'
  WHEN 2 THEN '接缝平整，尺码偏小半档。'
  WHEN 3 THEN '包装含中文说明，无替换配件。'
  WHEN 4 THEN '适合短时练习，不作竞赛配置。'
  WHEN 5 THEN '表层耐汗，清洗时不用漂白剂。'
  WHEN 6 THEN '入门规格，长时间使用需分段适应。'
  WHEN 7 THEN '扣件可单手调整，收纳体积较小。'
  WHEN 8 THEN '材质偏软，潮湿后应充分晾干。'
  WHEN 9 THEN '基础版无电子功能，维护简单。'
  WHEN 10 THEN '颜色以实物为准，拆封前核对规格。'
  WHEN 11 THEN '适配日常训练，专业配件需另购。'
  WHEN 12 THEN '边缘包胶，接触皮肤处没有硬角。'
  WHEN 13 THEN '单件装，出门前检查固定是否牢靠。'
  WHEN 14 THEN '面料快干，连续使用后需要清洁。'
  WHEN 15 THEN '标准版型，宽松需求可选大一号。'
  WHEN 16 THEN '不含安装服务，说明书列有尺寸表。'
  WHEN 17 THEN '适合室内与晴天，雨后及时擦干。'
  WHEN 18 THEN '握持区有浅纹，厚度偏薄。'
  WHEN 19 THEN '折叠收纳方便，避免重物长期挤压。'
  WHEN 20 THEN '基础材质无保温层，夏季使用更合适。'
  WHEN 21 THEN '配色低调，反光面积较小。'
  WHEN 22 THEN '开合顺畅，首次使用先做静态试装。'
  WHEN 23 THEN '无香型处理，清洁后自然通风。'
  WHEN 24 THEN '尺寸标注清楚，特殊体型先量围度。'
  WHEN 25 THEN '日常耐磨，尖锐物可能划伤表面。'
  WHEN 26 THEN '配件数量见包装清单，缺件可退换。'
  WHEN 27 THEN '重量较轻，不含竞速强化结构。'
  WHEN 28 THEN '内侧触感平滑，缝线位置避开受力点。'
  WHEN 29 THEN '旋钮阻尼适中，调整后要复查锁定。'
  WHEN 30 THEN '弹性中等，长期不用宜平放保存。'
  WHEN 31 THEN '基础防泼水，不等同于完全防水。'
  WHEN 32 THEN '包装简洁，赠品不作为保修部件。'
  WHEN 33 THEN '适合新手试用，强度升级需另选规格。'
  WHEN 34 THEN '表面易清洁，不能高温烘干。'
  WHEN 35 THEN '固定点较少，安装顺序见图示。'
  WHEN 36 THEN '常规尺码有现货，偏码款库存较少。'
  WHEN 37 THEN '材料气味轻，首次使用前建议通风。'
  WHEN 38 THEN '适合低强度练习，磨损后及时更换。'
  ELSE '售后按页面规则，使用前保留完整包装。'
END
WHERE rowid > 7;

-- Replace row-number arithmetic with irregular but plausible catalogue values.
UPDATE products
SET rating_count = max(3, rating_count + CASE (rowid % 13)
      WHEN 0 THEN 41 WHEN 1 THEN -9 WHEN 2 THEN 67 WHEN 3 THEN -28
      WHEN 4 THEN 12 WHEN 5 THEN 93 WHEN 6 THEN -17 WHEN 7 THEN 34
      WHEN 8 THEN -36 WHEN 9 THEN 58 WHEN 10 THEN 5 WHEN 11 THEN 76 ELSE -22 END),
    sales_count = max(1, sales_count + CASE (rowid % 17)
      WHEN 0 THEN 125 WHEN 1 THEN -47 WHEN 2 THEN 309 WHEN 3 THEN -118
      WHEN 4 THEN 62 WHEN 5 THEN 441 WHEN 6 THEN -205 WHEN 7 THEN 93
      WHEN 8 THEN -36 WHEN 9 THEN 257 WHEN 10 THEN -84 WHEN 11 THEN 176
      WHEN 12 THEN 18 WHEN 13 THEN 352 WHEN 14 THEN -139 WHEN 15 THEN 71 ELSE -11 END),
    base_price_minor = max(900, base_price_minor + CASE (rowid % 19)
      WHEN 0 THEN 300 WHEN 1 THEN -200 WHEN 2 THEN 700 WHEN 3 THEN -500
      WHEN 4 THEN 100 WHEN 5 THEN 1200 WHEN 6 THEN -300 WHEN 7 THEN 450
      WHEN 8 THEN -650 WHEN 9 THEN 850 WHEN 10 THEN 0 WHEN 11 THEN 250
      WHEN 12 THEN -150 WHEN 13 THEN 950 WHEN 14 THEN -400 WHEN 15 THEN 550
      WHEN 16 THEN -250 WHEN 17 THEN 150 ELSE 400 END)
WHERE rowid > 7;

