-- Batch numbers were fixture-generation artefacts.  The remaining model/style
-- words already make all 220 marketplace listings distinct.
UPDATE products
SET title = trim(substr(title, 1, instr(title, '（批次 ') - 1))
WHERE instr(title, '（批次 ') > 0;
